function sanitizeName(name, maxLength) {
  if (name == null) return "";
  return name.replace(/[^a-zA-Z]/g, " ").substring(0, maxLength);
}

function extractMiddleName(fullName) {
  if (!fullName) return '';
  const nameParts = fullName.trim().split(' ');
  if (nameParts.length > 2) {
    return nameParts[1].charAt(0).toUpperCase();
  }
  return '';
}

const firstName = steps.trigger.payload.personalInformation.firstName;
const lastName = steps.trigger.payload.personalInformation.lastName;
const middleName = extractMiddleName(firstName);

return {
  firstName: sanitizeName(firstName, 15),
  lastName: sanitizeName(lastName, 25),
  middleName: sanitizeName(middleName, 15),
};

function isBlank(name) {
  return !name || name.trim() === "" || !/[a-zA-Z]/.test(name);
}

const allowedStates = steps.constants.output.states;
const state = steps.trigger.payload.personalInformation.state;
const validState = allowedStates.includes(state);

const firstName = steps.parsed_name.output.firstName;
const lastName = steps.parsed_name.output.lastName;
const validName = !isBlank(firstName) && !isBlank(lastName);

const source = steps.trigger.payload.subAccountUuid || "";
const sourceName = steps.constants.output.subAccountIdsMap[source] || ""
const biddingActive = !sourceName || steps.constants.output.activeBidding[sourceName] === true

console.log(`Bidding status for ${sourceName}: ${biddingActive}`);

if (biddingActive && validState && validName) return;

if (!biddingActive) {
  return { response: { status: 200, body: {
    lead_id: steps.trigger.payload.leadUuid,
    status: "rejected",
    reason: "bidding not active",
  }}};
}

if (!validState) {
  return { response: { status: 200, body: {
    lead_id: steps.trigger.payload.leadUuid,
    status: "rejected",
    reason: "ineligible state",
  }}};
}

if (!validName) {
  return { response: { status: 200, body: {
    lead_id: steps.trigger.payload.leadUuid,
    status: "rejected",
    reason: "invalid name",
  }}};
}

function transformToSalesforceFormat(inputData, traceId, parsedName) {
  const personal = inputData.personalInformation || {};
  const loan = inputData.loanInformation || {};
  const mortgage = inputData.mortgageInformation || {};
  const credit = inputData.creditInformation || {};
  const financial = inputData.financialInformation || {};
  const education = inputData.educationInformation || {};
  const legal = inputData.legalInformation || {};
  const session = inputData.sessionInformation || {};

  const mapEmploymentStatus = (status) => {
    if (!status) return 'Other';
    const statusMap = {
      'employed': 'Employed', 'employed_full_time': 'employed_full_time',
      'employed_part_time': 'employed_part_time', 'military': 'Military',
      'not_employed': 'not_employed', 'self_employed': 'self_employed',
      'retired': 'Retired', 'other': 'Other'
    };
    return statusMap[status.toLowerCase()] || 'Other';
  };

  const mapEducationLevel = (level) => {
    if (!level) return 'Other';
    const levelMap = {
      'high_school': 'high_school', 'associate': 'Associate', 'bachelors': 'Bachelors',
      'masters': 'Masters', 'doctorate': 'Doctorate', 'other_grad_degree': 'other_grad_degree',
      'certificate': 'Certificate', 'did_not_graduate': 'did_not_graduate',
      'still_enrolled': 'still_enrolled', 'other': 'Other'
    };
    return levelMap[level.toLowerCase()] || 'Other';
  };

  const mapLoanPurpose = (purpose) => {
    if (!purpose) return 'Other';
    const purposeMap = {
      'auto': 'Auto', 'auto_purchase': 'auto_purchase', 'auto_refinance': 'auto_refinance',
      'baby': 'Baby', 'boat': 'Boat', 'business': 'Business', 'car_repair': 'car_repair',
      'cosmetic': 'Cosmetic', 'credit_card_refi': 'credit_card_refi',
      'debt_consolidation': 'debt_consolidation', 'emergency': 'Emergency',
      'engagement': 'Engagement', 'green': 'Green', 'home_improvement': 'home_improvement',
      'home_purchase': 'home_purchase', 'home_refi': 'home_refi',
      'household_expenses': 'household_expenses', 'large_purchases': 'large_purchases',
      'life_event': 'life_event', 'medical_dental': 'medical_dental',
      'motorcycle': 'Motorcycle', 'moving_relocation': 'moving_relocation', 'other': 'Other',
      'rv': 'Rv', 'special_occasion': 'special_occasion', 'student_loan': 'student_loan',
      'student_loan_refi': 'student_loan_refi', 'taxes': 'Taxes', 'unknown': 'Unknown',
      'vacation': 'Vacation', 'wedding': 'Wedding'
    };
    return purposeMap[purpose.toLowerCase()] || 'Other';
  };

  const mapPaymentFrequency = (frequency) => {
    if (!frequency) return 'Monthly';
    const frequencyMap = {
      'weekly': 'Weekly', 'biweekly': 'biweekly',
      'twice_monthly': 'twice_monthly', 'monthly': 'Monthly'
    };
    return frequencyMap[frequency.toLowerCase()] || 'Monthly';
  };

  const mapCreditRating = (rating) => {
    if (!rating) return 'Poor (<600)';
    const ratingMap = {
      'excellent': 'Excellent (720+)', 'good': 'Good (660-719)',
      'fair': 'Fair (620-659)', 'poor': 'Poor (<600)',
      'limited': 'Poor (<600)', 'unknown': 'Poor (<600)'
    };
    return ratingMap[rating.toLowerCase()] || 'Poor (<600)';
  };

  const mapPropertyStatus = (status) => {
    if (!status) return 'Rent';
    const statusMap = {
      'own_outright': 'Own Outright', 'own_with_mortgage': 'Own with Mortgage', 'rent': 'Rent'
    };
    return statusMap[status.toLowerCase()] || 'Rent';
  };

  const formatPhoneNumber = (phone) => {
    if (!phone) return '';
    const digits = phone.replace(/\D/g, '');
    if (digits.length === 10) {
      return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
    }
    return phone;
  };

  const formatSSN = (ssn) => {
    if (!ssn) return '';
    return ssn.replace(/\D/g, '');
  };

  const safeBirthDate = (dob) => {
    if (!dob) return '1901-01-01';
    const d = new Date(dob + 'T00:00:00Z');
    if (isNaN(d.getTime())) return '1900-01-01';
    if (d.getUTCFullYear() < 1900) return '1900-01-01';
    return dob;
  };

  return {
    "Last_Name__c": parsedName.lastName || '',
    "Middle_Name__c": parsedName.middleName || '',
    "First_Name__c": parsedName.firstName || '',
    "State__c": personal.state || '',
    "City__c": personal.city || '',
    "Zip__c": personal.zipcode || '',
    "Email__c": personal.email || '',
    "Phone__c": formatPhoneNumber(personal.primaryPhone),
    "BirthDate__c": safeBirthDate(personal.dateOfBirth),
    "Street__c": personal.address1 || '',
    "AptSuite__c": personal.address2 || '',
    "LoanAmount__c": loan.loanAmount || 0,
    "LoanPurpose__c": mapLoanPurpose(loan.purpose),
    "IncomePmtFrequency__c": mapPaymentFrequency(financial.employmentPayFrequency),
    "AnnualIncomeBeforeTaxes__c": financial.annualIncome || 0,
    "EmploymentStatus__c": mapEmploymentStatus(financial.employmentStatus),
    "EducationLevel__c": mapEducationLevel(education.educationLevel),
    "SocialSecurityNumber__c": formatSSN(personal.ssn),
    "RentOrOwn__c": mapPropertyStatus(mortgage.propertyStatus),
    "ApproximateCreditRating__c": mapCreditRating(credit.providedCreditRating),
    "LeadUUID__c": inputData.leadUuid,
    "SubaccountUUID__c": inputData.subAccountUuid,
    "Source__c": "Engine",
    "ProspectTraceId__c": traceId,
    "TCPAConsentFlag__c": legal.consentsToTcpa,
    "FCRAConsentFlag__c": legal.consentsToFcra,
    "User_Agent__c": (session.userAgent || '').slice(0, 255),
    "User_IP__c": session.ipAddress,
  };
}

try {
  return transformToSalesforceFormat(
    steps.trigger.payload,
    execution.trace_id,
    steps.parsed_name.output
  );
} catch (error) {
    console.error(`Error transforming data [${execution.trace_id}]:`, error?.message, error?.stack);
    return { response: { status: 500, body: {
      lead_id: steps.trigger.payload.leadUuid,
      status: "error",
      reason: "prospect_body_transform_error",
      error_message: error?.message ?? String(error),
      error_stack: error?.stack,
    }}};
  }

async function getEquifaxToken(username, password) {
  const params = 'grant_type=client_credentials&scope=https://api.equifax.com/business/oneview/consumer-credit/v1';
  const res = await fetch('https://api.equifax.com/v2/oauth/token', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Authorization': 'Basic ' + btoa(`${username}:${password}`),
      'User-Agent': 'axios/1.7.0',
      'Accept': 'application/json, text/plain, */*',
    },
    body: params,
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Equifax Token Error: ${res.status} - ${text}`);
  }
  const data = await res.json();
  if (!data.access_token) throw new Error('Access token not found in response');
  return data.access_token;
}

// Returns a 9-digit SSN string, or null if the lead has no usable SSN.
// Tolerates "673-31-3292", "673 31 3292", "673313292_test78", etc.
function extractSSN(rawSsn) {
  if (!rawSsn) return null;
  const digits = String(rawSsn).replace(/[^0-9]/g, '').slice(0, 9);
  return digits.length === 9 ? digits : null;
}

function formatRequestBody(body, firstName, lastName) {
  if (!body.dateOfBirth) throw new Error('personalInformation.dateOfBirth missing from payload');

  const formattedSSN = extractSSN(body.ssn);
  if (body.ssn && !formattedSSN) {
    console.log(`SSN present but unusable after stripping non-numerics ("${body.ssn}"); submitting without SSN`);
  }
  if (!formattedSSN) {
    console.log('No SSN on lead — submitting Equifax pull on name + DOB + address');
  }

  const [year, month, day] = body.dateOfBirth.split('-');
  const formattedDOB = `${month}${day}${year}`;

  const consumers = {
    name: [{
      identifier: 'current',
      firstName,
      lastName,
      middleName: '',
      suffix: '',
    }],
    dateOfBirth: formattedDOB,
    addresses: [{
      identifier: 'current',
      streetName: `${body.address1 ?? ''} ${body.address2 ?? ''}`.trim(),
      city: body.city,
      state: body.state,
      zip: body.zipcode,
    }],
  };

  // Only include socialNum when we actually have one — omit the key entirely,
  // never send it empty.
  if (formattedSSN) {
    consumers.socialNum = [{
      identifier: 'current',
      number: formattedSSN,
    }];
  } else {
    // No SSN: phone strengthens the name+DOB+address match when it's a clean 10 digits
    let phone = String(body.primaryPhone ?? '').replace(/[^0-9]/g, '');
    if (phone.length === 11 && phone.startsWith('1')) phone = phone.slice(1);
    if (phone.length === 10) {
      consumers.phoneNumbers = [{ identifier: 'current', number: phone }];
    }
  }

  return {
    consumers,
    customerReferenceIdentifier: 'Pennie Management',
    customerConfiguration: {
      equifaxUSConsumerCreditReport: {
        memberNumber: '402FZ14896',
        securityCode: 'N2N',
        pdfComboIndicator: 'N',
        customerCode: 'ISTS',
        multipleReportIndicator: '1',
        ECOAInquiryType: 'Individual',
        models: [{ identifier: '05402' }],
        endUserInformation: {
          endUsersName: '',
          permissiblePurposeCode: 'Null',
        },
      },
    },
  };
}

async function makeEquifaxRequest(token, body) {
  const res = await fetch(
    'https://api.equifax.com/business/oneview/consumer-credit/v1/reports/credit-report',
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
        'User-Agent': 'axios/1.7.0',
        'Accept': 'application/json, text/plain, */*',
      },
      body: JSON.stringify(body),
    }
  );
  if (!res.ok) {
    const text = await res.text();
    return { error: true, statusCode: res.status, message: text };
  }
  const data = await res.json();
  return { error: false, statusCode: 200, data };
}

async function makeEquifaxRequestWithRetry(token, body) {
  let result = await makeEquifaxRequest(token, body);
  if (result.error && result.statusCode >= 500 && result.statusCode < 600) {
    console.log(`Equifax first attempt failed ${result.statusCode}, retrying after 250ms...`);
    await new Promise(r => setTimeout(r, 250));
    result = await makeEquifaxRequest(token, body);
  }
  return result;
}

const personal = payload.personalInformation ?? {};
const body = { ...personal, leadUuid: payload.leadUuid };
const firstName = steps.parsed_name.output.firstName;
const lastName = steps.parsed_name.output.lastName;

try {
  const accessToken = await getEquifaxToken(
    process.env.EQUIFAX_USERNAME,
    process.env.EQUIFAX_PASSWORD
  );

  const formattedBody = formatRequestBody(body, firstName, lastName);
  const result = await makeEquifaxRequestWithRetry(accessToken, formattedBody);

  if (result.error) {
    console.error(`Equifax credit report error [${execution.trace_id}]: ${result.statusCode} - ${result.message}`);
     return {
        response: {
          status: result.statusCode ?? 500,
          body: {
            lead_id: body.leadUuid,
            status: 'error',
            reason: 'equifax_api_error',
            upstream_status: result.statusCode,
            upstream_body: (() => { try { return JSON.parse(result.message); } catch { return result.message; } })(),
          },
        },
      };
  }

  const fraudReports = result.data?.consumers?.equifaxUSConsumerCreditReport ?? [];
  const hasFraudCodeL = fraudReports.some(r =>
    (r?.fraudIDScanAlertCodes ?? []).some(c => c?.code === 'L')
  );
  if (hasFraudCodeL) {
    console.log(`Fraud ID Scan alert code L [${execution.trace_id}]: rejecting lead ${body.leadUuid}`);
    return {
      ...result.data,
      response: {
        status: 200,
        body: {
          lead_id: body.leadUuid,
          status: 'rejected',
          reason: 'unqualified_lead',
        },
      },
    };
  }

  return result.data;
} catch (error) {
  console.error(`Error in equifax_credit_report [${execution.trace_id}]:`, error.message, error.stack);
   return {
      response: {
        status: 500,
        body: {
          lead_id: body.leadUuid,
          status: 'error',
          reason: 'equifax_script_error',
          error_message: error?.message ?? String(error),
        },
      },
    };
}

// generate_trades_body
// Translates: steps.equifax_credit_report.$return_value.data → steps.equifax_credit_report.output
// Translates: steps.create_prospect.$return_value.id → steps.create_prospect.output.body.id
//   (Salesforce node wraps response as { status, body: { id, success, errors } })
// Translates: steps.trigger.event.body → payload
// Translates: steps.trigger.context.trace_id → execution.trace_id
// Translates: $.respond + $.flow.exit → return { response: {...} }
// Removes: makeSalesforceRequest() call to Pipedream endpoint (patch_prospect is lower priority — TODO)
// Removes: Slack axios call

try {
  const eqxCreditReport = steps.equifax_credit_report.output;
  const {
    consumers: {
      equifaxUSConsumerCreditReport: [creditReport = {}] = [],
    } = {},
  } = eqxCreditReport;
  const trades = creditReport.trades || [];

  console.log(`Credit Report: ${eqxCreditReport.status}, with ${trades.length} trades.`);

  const prospectId = steps.create_prospect.output.body.id;

  if (eqxCreditReport.status !== 'completed' || trades.length === 0) {
    console.log(`Rejected: missing_credit_check for prospect ${prospectId} [${execution.trace_id}]`);
    // TODO: PATCH Salesforce prospect BidStatus__c=Rejected, RejectionReason__c="No equifax match"
    return {
      response: {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
        body: {
          lead_id: payload.leadUuid,
          status: 'rejected',
          reason: 'missing_credit_check',
        },
      },
    };
  }

  const score = creditReport.models?.find(m => m.modelNumber === '05402')?.score;
  const removeNullValues = (obj) => Object.fromEntries(
    Object.entries(obj).filter(([, value]) => value !== null)
  );
  const parsedTrades = trades.map(removeNullValues);

  return {
    prospectId,
    tradesJson: JSON.stringify({ trades: parsedTrades }),
    vantageScore: score,
  };
} catch (error) {
    console.error(`Failed generating trades [${execution.trace_id}]:`, error?.message, error?.stack);
    return {
      response: {
        status: 500,
        body: {
          lead_id: payload.leadUuid,
          status: 'error',
          reason: 'generate_trades_body_error',
          error_message: error?.message ?? String(error),
          error_stack: error?.stack,
        },
      },
    };
  }

const pt = steps.prospect_trades.output.body;
const engineBid = pt.engineBid;

// The sale, from whichever node decided it (#1414, Phase 7): tripoint_ping when it ran
// (every lead today; the not_applicable and deferred routes after the cutover), else the
// buyer_select node. It carries the winner's own facts (#1416): who bought, where the lead
// lands, the Salesforce routing code and the Success, Duplicate or Fail class, so nothing
// below holds a Tripoint literal. The sale is published on this step's output as `sale`,
// and patch_prospect_body reads it from there: one normalised shape, read in one place.
//
// TRANSITIONAL, removed with tripoint_ping at Stage C: an older tripoint_ping on the canvas
// carries either no `sale` (the script before 2026-09-22) or a `sale` without the winner
// facts (the Stage A script). Both are Tripoint, so they are completed with Tripoint's own
// values here, and Tripoint's result code classes are mapped here for them, the only copy
// of that mapping outside tripoint_ping itself.
// Its duplicate codes are TRIPOINT_DUPLICATE_RESULT_CODES in bid-resolver.ts (#1549).
const readSale = () => {
  const tp = steps.tripoint_ping?.output;
  let sale = tp?.sale ?? steps.buyer_select?.output?.sale ?? null;
  if (!sale && tp) {
    sale = {
      skipped: tp.skipped === true,
      accepted: tp.qualified === true,
      buyer_reference: tp.createLead?.id ?? null,
      result_code: tp.resultCode != null ? String(tp.resultCode) : null,
      partner_slug: tp.skipped === true ? null : 'tripoint',
    };
  }
  if (!sale) return null;
  if (sale.partner_slug === 'tripoint' && sale.response_class === undefined) {
    const rc = sale.result_code != null ? Number(sale.result_code) : null;
    let response_class = null;
    if (sale.accepted) response_class = 'Success';
    else if (rc != null) response_class = [1002, 1003, 1004, 1005, 1020].includes(rc) ? 'Duplicate' : 'Fail';
    sale = {
      ...sale,
      partner_name: 'Tripoint',
      click_url: sale.accepted ? (steps.constants.output.TripointClickUrl ?? null) : null,
      routing_code: sale.accepted ? 2 : null,
      response_class,
    };
  }
  return sale;
};
const sale = readSale();

// What patch_prospect_reject writes on a rejection (#1471): the two fields it wrote by
// template today, plus the class of a declined sale, so Salesforce can tell a duplicate the
// buyer already holds from a lead nobody wanted. The class is the sale's own (#1416).
// Tripoint_Response__c is Tripoint's field, so it is written only when Tripoint declined;
// Salesforce has no field for another buyer's class yet. A rejection with no class (a zero
// bid, a 502 fault, a buyer error) carries the two fields alone, which is why this is
// built here and not by the node's body template: a template cannot leave a field out.
// The node's body is {{steps.build_response_body.output.reject_patch}}.
const rejectPatch = (reason, s) => {
  const patch = { BidStatus__c: 'Rejected', RejectionReason__c: reason };
  if (s && s.partner_slug === 'tripoint' && s.response_class) patch.Tripoint_Response__c = s.response_class;
  return patch;
};

// Early rejection: no bid
if (engineBid === 0) {
  return {
    isRejected: true,
    body: {
      lead_id: payload.leadUuid,
      status: 'rejected',
      reason: 'unqualified_lead',
    },
    reject_patch: rejectPatch('unqualified_lead', null),
    sale,
  };
}

// A click sold buyer on a KNOWN no (#1544): when the known_no_gate node said the node
// that decided this lead gave a known no, and the buyer_click_check node routed eligible,
// the lead is offered to that buyer instead of rejected. The buyer is sold when the lead
// clicks, not now. Every fact about the buyer (its slug, name, landing page and
// Salesforce routing code) comes from the check's output, so no buyer is named here and
// a second click buyer needs no script change. The check's click URL carries the
// placeholder {prospect_id}, replaced by the created prospect's id.
//
// `click_offer` records the decision whenever the gate ran, offered or not, with the
// reason; without the gate node on the canvas nothing here runs. A lead the deciding node
// sold is never offered again, whatever the gate says.
const readClickOffer = () => {
  const gate = steps.known_no_gate?.output;
  if (!gate) return null;
  const check = steps.buyer_click_check?.output ?? null;
  const decision = { known_no: gate.known_no === true, check_route: check?._route ?? null, offered: false, reason: null };
  const refuse = (reason) => ({ decision: { ...decision, reason }, sale: null });
  if (!decision.known_no) return refuse('not_a_known_no');
  if (sale && sale.accepted === true) return refuse('sold_by_deciding_node');
  if (!check) return refuse('check_not_run');
  if (check._route !== 'eligible') return refuse(check.reason ?? 'not_eligible');
  if (typeof check.partner_slug !== 'string' || !check.partner_slug) return refuse('check_names_no_buyer');
  if (typeof check.click_url !== 'string' || !check.click_url) return refuse('no_click_url');
  if (!check.click_url.includes('{prospect_id}')) return refuse('click_url_has_no_prospect_id');
  const prospectId = steps.create_prospect?.output?.body?.id;
  if (!prospectId) return refuse('no_prospect_id');
  return {
    decision: { ...decision, offered: true, reason: 'offered' },
    sale: {
      skipped: false,
      accepted: true,
      buyer_reference: null,
      result_code: null,
      partner_slug: check.partner_slug,
      partner_name: check.partner_name ?? null,
      click_url: check.click_url.split('{prospect_id}').join(String(prospectId)),
      routing_code: check.external_routing_code ?? null,
      response_class: null,
      sold_on: 'click',
    },
  };
};
const clickOffer = readClickOffer();
const clickSale = clickOffer ? clickOffer.sale : null;
// The deciding node's own decline, kept beside the click sale so the prospect patch still
// records Tripoint's class (#1544).
const declinedSale = clickSale ? sale : null;
const offerSale = clickSale ?? sale;
const withClick = (out) => {
  if (clickOffer) out.click_offer = clickOffer.decision;
  if (declinedSale) out.declined_sale = declinedSale;
  return out;
};

// A sale that was made and not accepted rejects the lead exactly as `qualified === false`
// did before the node existed.
const declined = offerSale ? (!offerSale.skipped && offerSale.accepted === false) : false;
  if (declined) {
    return withClick({
      isRejected: true,
      body: {
        lead_id: payload.leadUuid,
        status: 'rejected',
        reason: 'unqualified_lead',
      },
      reject_patch: rejectPatch('unqualified_lead', sale),
      sale,
    });
  }

const sellOff           = pt.sellOff;
const altLandingPage    = pt.altLandingPage;
const testOfferLanguage = pt.testOfferLanguage;
const expLandingPage    = pt.expLandingPage;

const formatter    = new Intl.NumberFormat('en-US');
const maxLoanPmt   = formatter.format(pt.maxLoanPmt);
const maxLoanAmt   = formatter.format(pt.maxLoanAmt);
const firstName    = payload.personalInformation.firstName;
const formatedName = firstName.charAt(0).toUpperCase() + firstName.slice(1).toLowerCase();
const annualIncome = formatter.format(payload.financialInformation.annualIncome);

const constants = steps.constants.output;

// A sold lead lands where the winner says (#1416); before this a sell off lead was sent to
// Tripoint's constant whether or not Tripoint had taken it. A sell off lead nobody bought
// now takes the Pennie pages below, which is where a lead with no sale belongs.
const getRedirectUrl = () => {
  if (offerSale && offerSale.accepted && offerSale.click_url) return offerSale.click_url;
