// tripoint_ping: engine bidding workflow
// Updated 2026-05-08 to fail-fast on proxy timeouts/5xx and prevent duplicate /create sends.
//
// Changes from previous version:
//   1. Removed the try/catch that swallowed network errors and returned qualified:false silently
//   2. Throw on res.status >= 500 so proxy 504 (Tripoint upstream timeout) surfaces as a step failure
//   3. Removed unused `upstreamError` variable + return field (errors now propagate, engine logs error_message automatically)
//
// Also set in Step settings panel:
//   • Retries: 0   ← critical, prevents duplicate /create sends to Tripoint on transient errors
//
// Updated 2026-09-22 for the buyer_select cutover (#1414, Phase 7). Two fields ADDED,
// nothing removed or reordered, so every downstream reader of the old fields is unchanged:
//   • sale: the outcome in the shape the buyer_select node emits, so build_response_body
//     and patch_prospect_body read one shape whichever node decided the lead.
//   • sent_body_sha256: the hash of exactly what was sent, computed the way the node
//     computes would_send_body_sha256, so the Stage A parity report can compare them.
//     Null when nothing was sent or the sandbox has no Web Crypto (unmeasured, never a
//     wrong hash).
// The kept copy and its tests: apps/worker/src/engine/scripts/engine-bidding/.
//
// Updated 2026-09-24 (#1540): every path names what Tripoint answered, and no path
// throws any more. Two fields ADDED at the end of every return, nothing removed or
// reordered:
//   • tripoint_answer: accepted | declined | in_progress (1009) | invalid_data (the known
//     502 refusal) | null_id_fault (the known 502 glitch) | skipped | unknown. Unknown is
//     everything not positively recognised: any other 5xx, any 4xx (a firewall page
//     included), a 2xx that does not parse, is not ok or has no result code, a fetch that
//     throws, and a call still unanswered after 15 s, which is aborted (the node's own
//     timeout is 20 s). A second buyer may act only on a KNOWN no, because an unknown can
//     be a sale Tripoint made and never told us about.
//   • unknown_reason: why the answer is unknown (http_504, timeout, network_error,
//     unparseable_body, not_ok, no_result_code), null otherwise.
// An unknown answer is a no sale (qualified false, a sale with no class), so
// build_response_body rejects the lead with a normal response instead of the run failing.
// The per run failure page that the old throw produced is replaced by the aggregated
// Tripoint outage page, which counts these steps (lib/upstream-outage.ts).
// ─────────────────────────────────────────────────────────────────────────────

// The sale in the buyer_select node's shape (#1416): this script IS Tripoint, so the
// winner's facts are Tripoint's own, and build_response_body and patch_prospect_body
// read them from here exactly as they read them from the node for any other buyer.
// The class is the one the node computes from the buyer's rules: Success on an
// accept, Duplicate on a code in Tripoint's duplicate set, Fail on any other code,
// and none when Tripoint gave no code (the two 502 faults).
// The duplicate codes are the one list, TRIPOINT_DUPLICATE_RESULT_CODES in the Worker's
// bid-resolver.ts (#1549); a test holds this copy to it, because a script cannot import.
const tripointSale = (accepted, buyerReference, resultCode) => {
  let response_class = null;
  if (accepted) response_class = 'Success';
  else if (resultCode != null) response_class = [1002, 1003, 1004, 1005, 1020].includes(Number(resultCode)) ? 'Duplicate' : 'Fail';
  return {
    skipped: false,
    accepted,
    buyer_reference: buyerReference ?? null,
    result_code: resultCode != null ? String(resultCode) : null,
    partner_slug: 'tripoint',
    partner_name: 'Tripoint',
    click_url: accepted ? (steps.constants.output.TripointClickUrl ?? null) : null,
    routing_code: accepted ? 2 : null,
    response_class,
  };
};
const NO_SALE = tripointSale(false, null, null);

const pt = steps.prospect_trades.output.body;

// No-op when not a Tripoint sell-off: bail fast so the rest of the workflow
// behaves identically to the non-Tripoint path.
if (!pt.sellOff || pt.engineBid === 0) {
  return {
    skipped: true, qualified: null, createLead: null, resultCode: null,
    sale: {
      skipped: true, accepted: false, buyer_reference: null, result_code: null, partner_slug: null,
      partner_name: null, click_url: null, routing_code: null, response_class: null,
    },
    sent_body_sha256: null,
    tripoint_answer: 'skipped', unknown_reason: null,
  };
}

// Tripoint's minimum loan amount (2026-10-15). The buyer profile holds 2,000 (set
// 2026-10-13 at Sam's request) and buyer_select judges it, but this script never reads
// the profile, so it carries its own copy until buyer_select takes every lead and this
// node is removed. A change to the profile's minimum must be made here too. The refusal
// is the node's: an amount that is not a positive number is missing_lead_field before
// any comparison, so it can never pass the minimum, and a smaller one is
// loan_amount_below_min. The amount is read as parsePositiveAmount in
// packages/buyer-profile reads it; a script cannot import, so tripoint-loan-floor.test.ts
// holds this copy to that function.
const TRIPOINT_LOAN_AMOUNT_MIN = 2000;
const positiveAmount = (input) => {
  let n;
  if (typeof input === 'number') n = input;
  else if (typeof input === 'string') {
    const cleaned = input.trim().replace(/^\$/, '').replace(/,/g, '');
    if (!/^-?\d+(\.\d+)?$/.test(cleaned)) return null;
    n = Number(cleaned);
  } else return null;
  return Number.isFinite(n) && n > 0 ? n : null;
};
const loanAmount = positiveAmount(payload.loanInformation?.loanAmount);
const loanRefusal = loanAmount === null ? 'missing_lead_field'
  : loanAmount < TRIPOINT_LOAN_AMOUNT_MIN ? 'loan_amount_below_min' : null;
if (loanRefusal !== null) {
  return {
    skipped: true, qualified: null, createLead: null, resultCode: null,
    sale: {
      skipped: true, accepted: false, buyer_reference: null, result_code: null, partner_slug: null,
      partner_name: null, click_url: null, routing_code: null, response_class: null,
    },
    sent_body_sha256: null,
    tripoint_answer: 'skipped', unknown_reason: null,
    skip_reason: loanRefusal,
  };
}

const proxyPayload = {
  ...payload,
  personalInformation: {
    ...payload.personalInformation,
    ssn: String(payload.personalInformation?.ssn || '').replace(/\D/g, '').slice(0, 9),
  },
  unsecuredDebt: pt.tradeCalculations.engineDebt,
  maxUnsecuredDebt: pt.tradeCalculations.enrollableDebt,
  workflowId: 'engine-bidding',
  pennieLeadId: steps.create_prospect.output.body.id,
  executionId: execution.trace_id,
  leadType: 'prospect',
};

// Same canonical form as packages/buyer-profile payload.ts canonicalBodySha256: object
// keys sorted at every level, arrays kept in order, then JSON, then SHA-256 hex.
let sent_body_sha256 = null;
try {
  const canonicalise = (v) => {
    if (Array.isArray(v)) return v.map(canonicalise);
    if (v !== null && typeof v === 'object' && Object.getPrototypeOf(v) === Object.prototype) {
      const out = {};
      for (const k of Object.keys(v).sort()) out[k] = canonicalise(v[k]);
      return out;
    }
    return v;
  };
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(JSON.stringify(canonicalise(proxyPayload))));
  sent_body_sha256 = [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
} catch {
  sent_body_sha256 = null;
}

// An answer nobody could read (#1540): a no sale in every field older readers key on, with
// the reason it is unknown. Never a throw, so the lead gets a normal reject response.
const unknownAnswer = (reason, debug) => ({
  skipped: false,
  qualified: false,
  createLead: null,
  resultCode: null,
  debug,
  sale: NO_SALE,
  sent_body_sha256,
  tripoint_answer: 'unknown',
  unknown_reason: reason,
});

// Below the node's 20 s timeout, so the script decides the answer rather than the engine
// failing the step.
const TRIPOINT_TIMEOUT_MS = 15000;

let body = {};
let httpStatus = null;
let rawText = null;

const controller = new AbortController();
let timedOut = false;
const timer = setTimeout(() => { timedOut = true; controller.abort(); }, TRIPOINT_TIMEOUT_MS);
try {
  const res = await fetch('https://tripoint-proxy.trypennie.dev/leads/create', {
    method: 'POST',
    headers: {
      authorization: `Bearer ${env.TRIPOINT_PROXY_SECRET}`,
      'content-type': 'application/json',
    },
    body: JSON.stringify(proxyPayload),
    signal: controller.signal,
  });
  httpStatus = res.status;
  rawText = await res.text();
} catch (err) {
  const reason = timedOut ? 'timeout' : 'network_error';
  const message = err instanceof Error ? err.message : 'non Error thrown';
  console.warn(`tripoint answer unknown (${reason}): ${message}`);
  return unknownAnswer(reason, { httpStatus, rawText, parsed: null, error: message });
} finally {
  clearTimeout(timer);
}

if (httpStatus >= 500) {
    // Brian's proxy returns 502 when Tripoint's upstream GraphQL has ok:false.
    // The known intermittent fault is `createLead` returning null for a
    // non-nullable id: Tripoint's own schema-contract violation, not anything
    // we sent. Route those leads to the engine fallback (qualified=false) so
    // Engine gets a proper response instead of a 5xx. Every other 5xx (a real
    // proxy/network/timeout outage) is an unknown answer (#1540).
    let proxyBody = null;
    try { proxyBody = JSON.parse(rawText ?? ''); } catch {}
    const isTripointNullIdFault =
      proxyBody?.ok === false &&
      Array.isArray(proxyBody?.details) &&
      proxyBody.details.some((d) =>
        typeof d?.message === 'string' &&
        d.message.includes('Cannot return null for non-nullable field CreateLeadResponse.id')
      );

    if (isTripointNullIdFault) {
      console.warn('tripoint createLead null id: known transient Tripoint fault, routing to fallback');
      return {
        skipped: false,
        qualified: false,
        createLead: null,
        resultCode: null,
        tripointTransientFault: true,
        debug: { httpStatus, rawText, parsed: proxyBody },
        sale: NO_SALE,
        sent_body_sha256,
        tripoint_answer: 'null_id_fault',
        unknown_reason: null,
      };
    }

    // Tripoint rejects malformed lead data (bad email, phone, etc.) with the same
    // 502 wrapper the proxy uses for real outages. These are business rejections,
    // not infra faults: the lead data is bad and a retry won't help: so route
    // them to the engine fallback (qualified=false, → reject path in
    // build_response_body) instead of failing the whole execution.
    const rejectionDetail = Array.isArray(proxyBody?.details)
      ? proxyBody.details.find((d) =>
          typeof d?.message === 'string' && /^\s*invalid\b/i.test(d.message)
        )
      : null;
    const isTripointLeadRejection = proxyBody?.ok === false && !!rejectionDetail;

    if (isTripointLeadRejection) {
      const reason = rejectionDetail.message;
      console.warn(`tripoint lead rejected (${reason}): routing to reject path`);
      return {
        skipped: false,
        qualified: false,
        createLead: null,
        resultCode: null,
        tripointLeadRejected: true,
        rejectReason: reason,
        debug: { httpStatus, rawText, parsed: proxyBody },
        sale: NO_SALE,
        sent_body_sha256,
        tripoint_answer: 'invalid_data',
        unknown_reason: null,
      };
    }

    console.warn(`tripoint answer unknown (http_${httpStatus})`);
    return unknownAnswer(`http_${httpStatus}`, { httpStatus, rawText, parsed: proxyBody });
  }

let parsedOk = true;
try {
  body = rawText ? JSON.parse(rawText) : {};
  if (!rawText) parsedOk = false;
} catch {
  body = {};
  parsedOk = false;
}

const createLead = body?.data?.createLead ?? null;
const resultCode = createLead?.resultCode != null ? Number(createLead.resultCode) : null;

// Only a 2xx that parses, says ok and carries a numeric result code is an answer
// (#1540); anything else is unknown, whatever it contains.
let unknownReason = null;
if (httpStatus < 200 || httpStatus >= 300) unknownReason = `http_${httpStatus}`;
else if (!parsedOk || body === null || typeof body !== 'object') unknownReason = 'unparseable_body';
else if (body.ok !== true) unknownReason = 'not_ok';
else if (resultCode === null || !Number.isFinite(resultCode)) unknownReason = 'no_result_code';

if (unknownReason) {
  console.warn(`tripoint answer unknown (${unknownReason})`);
  return unknownAnswer(unknownReason, { httpStatus, rawText: rawText ?? null, parsed: body });
}

const qualified =
  body.ok === true &&
  (resultCode === 1000 || resultCode === 1001 ||
   (resultCode >= 1013 && resultCode <= 1017));

let tripoint_answer = 'declined';
if (qualified) tripoint_answer = 'accepted';
else if (resultCode === 1009) tripoint_answer = 'in_progress';

return {
  skipped: false,
  qualified,
  createLead,
  resultCode,
  debug: {
    httpStatus,
    rawText: rawText ?? null,
    parsed: body,
  },
  sale: tripointSale(qualified, createLead?.id ?? null, resultCode),
  sent_body_sha256,
  tripoint_answer,
  unknown_reason: null,
};

// Known no gate (#1544): may a click sold buyer be offered this lead?
//
// Only on a KNOWN no from the node that decided the lead. An unknown answer (a timeout,
// a proxy 5xx, 1009 in progress, a buyer error, an outcome nobody could read) may be a
// sale the buyer made and never told us about, so offering the lead again could sell it
// twice (Dan, 2026-09-24). Anything this script does not recognise is not a known no.
//
// The deciding node is read by the same rule build_response_body reads its sale by:
// tripoint_ping when it carries a sale, else buyer_select when it carries one, else
// tripoint_ping. So the gate keeps working when buyer_select sells live at Stage B and
// tripoint_ping no longer runs.
//
// Both nodes' answers are put into tripoint_ping's words (#1540) and judged by the ONE
// list below (#1653), so a Tripoint answer is a known no or not whichever node recorded it.
//
//   tripoint_ping: its tripoint_answer, as it stands. An older script that names no
//                  answer is not a known no.
//   buyer_select:  a no_sale the buyer declined (declined_by_buyer) that carries the
//                  buyer's answer (a class) is declined, except where it cannot be told
//                  from Tripoint's 1009 in progress:
//                    a result code: Tripoint's 1009 is in_progress, any other is declined.
//                    no result code, detail http 5xx: declined. Tripoint's decline rules
//                      decline a 5xx only on its two known 502 answers, invalid data and
//                      the null id, which tripoint_ping calls invalid_data and null_id_fault.
//                    no result code otherwise: unknown for Tripoint, whose 1009 is also a
//                      decline by its rules; declined for any other buyer.
//                  A decline with no class (replayed from an earlier attempt) is unknown.
//                  Every other route or reason is named by its reason, never a known no.
//
// The Branch after this node sends known_no true to the buyer_click_check node.
const KNOWN_NO_ANSWERS = ['declined', 'invalid_data', 'null_id_fault'];
// Tripoint's "duplicate submission already in progress", the code tripoint_ping names
// in_progress (a test holds the two together).
const TRIPOINT_IN_PROGRESS_CODES = ['1009'];

const buyerSelectAnswer = (out) => {
  if (out._route !== 'no_sale' || out.reason !== 'declined_by_buyer') return typeof out.reason === 'string' ? out.reason : null;
  const sale = out.sale ?? {};
  if (sale.response_class == null) return 'unknown';
  const tripoint = sale.partner_slug === 'tripoint';
  if (sale.result_code != null) return tripoint && TRIPOINT_IN_PROGRESS_CODES.includes(String(sale.result_code)) ? 'in_progress' : 'declined';
  if (typeof out.detail === 'string' && /^http 5\d\d$/.test(out.detail)) return 'declined';
  return tripoint ? 'unknown' : 'declined';
};

const tp = steps.tripoint_ping?.output ?? null;
const bs = steps.buyer_select?.output ?? null;

let decidedBy = null;
if (tp && tp.sale) decidedBy = 'tripoint_ping';
else if (bs && bs.sale) decidedBy = 'buyer_select';
else if (tp) decidedBy = 'tripoint_ping';

let answer = null;
if (decidedBy === 'tripoint_ping') answer = typeof tp.tripoint_answer === 'string' ? tp.tripoint_answer : null;
if (decidedBy === 'buyer_select') answer = buyerSelectAnswer(bs);
return { known_no: answer !== null && KNOWN_NO_ANSWERS.includes(answer), decided_by: decidedBy, answer };
